func TestNotificationPublishAndReadScope(t *testing.T){db,e:=gorm.Open(sqlite.Open("file:notification_test?mode=memory&cache=shared"),&gorm.Config{});if e!=nil{t.Fatal(e)};if e=db.AutoMigrate(&models.User{},&models.Announcement{},&models.Notification{});e!=nil{t.Fatal(e)};u:=models.User{Name:"Parent",Email:"np@test",Role:"parent",Active:true};if e=db.Create(&u).Error;e!=nil{t.Fatal(e)};r:=repository.NewNotificationRepository(db);s:=NewNotificationService(r,db);a,e:=s.CreateAnnouncement(models.Announcement{CreatedBy:u.ID,Title:"Fees",Body:"Payment due",Category:"fees",Audience:models.AudienceParents});if e!=nil{t.Fatal(e)};n,e:=s.Publish(a.ID);if e!=nil||n!=1{t.Fatalf("publish: n=%d e=%v",n,e)};items,e:=s.List(u.ID);if e!=nil||len(items)!=1{t.Fatalf("list: %d %v",len(items),e)};if e=s.MarkRead(u.ID,items[0].ID);e!=nil{t.Fatal(e)};var got models.Notification;db.First(&got,"id=?",items[0].ID);if !got.Read{t.Fatal("expected read")};_ = uuid.Nil}
